def migrate_recipients(apps, schema_editor):
    """Convierte cada `EmailRecipient` en `Subscriber` + `Subscription`.

    Las filas existentes vienen de una carga manual del operador, así que se
    asumen confirmadas (`source='admin'`, decisión 3 de la propuesta 030). Se
    normaliza el correo porque `Subscriber` lo usa como identidad.
    """
    EmailRecipient = apps.get_model('core', 'EmailRecipient')
    EmailRecipientList = apps.get_model('core', 'EmailRecipientList')
    Subscriber = apps.get_model('core', 'Subscriber')
    Subscription = apps.get_model('core', 'Subscription')

    now = timezone.now()
    for row in EmailRecipient.objects.all().iterator():
        email = (row.email or '').strip().lower()
        if not email:
            continue
        subscriber, _created = Subscriber.objects.get_or_create(
            email=email,
            defaults={'source': 'admin', 'confirmed_at': now},
        )
        Subscription.objects.get_or_create(
            subscriber=subscriber,
            recipient_list_id=row.recipient_list_id,
            defaults={'source': 'admin'},
        )

    # La lista principal es la que el operador ya venía usando. Se reconoce por
    # nombre (`newsletter`) y, si ese nombre no existe, por ser la ÚNICA lista:
    # con una sola no hay ambigüedad posible.
    #
    # El respaldo importa porque sin él una lista llamada de otra forma quedaba
    # fuera de la audiencia automática y `0003` creaba una lista vacía como
    # principal: las direcciones que el operador había cargado a mano dejaban de
    # recibir avisos y pronósticos, sin ningún error visible.
    if not EmailRecipientList.objects.filter(is_default=True).exists():
        lists = EmailRecipientList.objects.all()
        if lists.count() == 1:
            lists.update(is_default=True)


